const ICONS: [RegExp, string][] = [[/class 10|10th|secondary/i, "📘"], [/class 12|12th|higher|intermediate/i, "🎒"], [/iti|trade/i, "🔧"], [/diploma|polytechnic/i, "📜"], [/post|master/i, "🎓"], [/under|graduate|bachelor|degree/i, "🎓"]];
/** Emoji icon for an education level (or any label); a book is the fallback. */
export const iconFor = (label: string): string => ICONS.find(([re]) => re.test(label))?.[1] ?? "📘";
